<tr><td>(Hofland)</td><td><strong>Jan Fekke Hofland</strong> <em>(boerenknecht)</em> × Guurtje Rijding <em>(dienstmeid)</em> (m. 1824 Zijpe)</td><td>~1796</td><td>Barsingerhorn / Zijpe</td><td><strong>Verified</strong> &mdash; 1824 Zijpe marriage akte</td></tr>
<tr><td>(Grevenstuk)</td><td><strong>Bernardus Grevenstuk × Leentje Tiggelman</strong> (m. 1871 Dirksland)</td><td>b. Leentje 1852</td><td>Goeree-Overflakkee</td><td><strong>Verified</strong> &mdash; 1871 Dirksland marriage akte</td></tr>
<tr><td>(Tiggelman)</td><td><strong>Hendrik Tiggelman × Adriaantje Koppenaal</strong> (m. 1837 Middelharnis)</td><td>~1810s</td><td>Goeree-Overflakkee</td><td><strong>Verified</strong> &mdash; 1837 Middelharnis marriage akte (names two further generations)</td></tr>
<tr><td>(Tiggelman, deeper)</td><td><strong>Gerrit Tiggelman × Niesje Verweij</strong>; above them <strong>Cornelis Tichelman × Sara Kattestaart</strong> and <strong>Brandijn Verweij × Jacomijna Mulder</strong></td><td>later 1700s</td><td>Goeree-Overflakkee</td><td><strong>Verified</strong> as named in the 1837 akte; their own records not yet pulled</td></tr>
<tr><td>(Koppenaal, deeper)</td><td><strong>Leendert Koppenaal × Heijtje van der Velde</strong>; among the grandparents <strong>Abram Koppenaal</strong> and <strong>Jan van der Velde × Teuntje Vreeswijk</strong></td><td>later 1700s</td><td>Goeree-Overflakkee</td><td><strong>Verified</strong> as named in the 1837 akte; their own records not yet pulled</td></tr>
